"use client";
import React, { useState } from "react";
import axios from "axios";
import { useRouter } from "next/navigation";
import Sidebar from "../../components/sidebar";
import Navbar from "../../components/Navbar";
import { HiArrowNarrowLeft } from "react-icons/hi";

const Addnewuser = () => {
  const [inputs, setInputs] = useState({
    idEncadrant: "",
    nom: "",
    prenom: "",
    email: "",
    motDePasse: "",
    annee: "",
    classe: "",
    filiere: "",
  });

  const [errorMessage, setErrorMessage] = useState("");
  const [successMessage, setSuccessMessage] = useState("");

  const handleChange = (event) => {
    const { name, value } = event.target;
    setInputs((prevValues) => {
      const newInputs = { ...prevValues, [name]: value };
      console.log("Updated Inputs:", newInputs); // Vérifie la mise à jour des valeurs
      return newInputs;
    });
  };

  const router = useRouter();

  const handleSubmit = async (event) => {
    event.preventDefault();

    console.log("Final Inputs:", inputs); // Vérifie les valeurs avant l'envoi

    if (!inputs.email.includes("@")) {
      setErrorMessage("L'adresse email n'est pas valide.");
      return;
    }

    if (inputs.motDePasse.length < 6) {
      setErrorMessage("Le mot de passe doit contenir au moins 6 caractères.");
      return;
    }

    try {
      setErrorMessage("");
      setSuccessMessage("");

      await axios.post("http://localhost:5000/api/addEncadrant", inputs);
      setSuccessMessage("Encadrant ajouté avec succès !");
      router.push("/users/readEnca/");
    } catch (err) {
      setErrorMessage("Erreur lors de l'ajout de l'encadrant.");
      console.error("Erreur lors de l'ajout de l'encadrant:", err);
    }
  };

  return (
    <div className="flex h-screen w-screen bg-gray-50">
      {/* Sidebar */}
      <Sidebar className="h-screen" />

      <div className="w-full flex flex-col h-screen">
        {/* Navbar */}
        <Navbar />

        {/* Contenu principal */}
        <div className="w-full flex-1 py-5 flex flex-col items-center overflow-auto">
          <div className="bg-white shadow-2xl rounded-2xl p-8 w-full max-w-lg border border-gray-100 transform transition-transform duration-300 hover:scale-101">
            {/* Bouton de retour */}
            <button
              onClick={() => router.push("/users/readEnca")}
              className="mb-5 flex items-center text-blue-600 hover:text-blue-800 transition font-medium text-lg"
            >
              <HiArrowNarrowLeft className="mr-2 text-2xl" />
            </button>

            {/* Titre */}
            <h1 className="text-3xl font-bold text-center text-gray-800 mb-6">
              Ajouter un Encadrant
            </h1>

            {/* Affichage des messages */}
            {errorMessage && <div className="text-red-500 mb-4">{errorMessage}</div>}
            {successMessage && <div className="text-green-500 mb-4">{successMessage}</div>}

            {/* Formulaire */}
            <form onSubmit={handleSubmit}>
              {/* ID Encadrant */}
              <div className="mb-4">
                <label htmlFor="idEncadrant" className="block text-sm font-medium text-gray-700 mb-1">
                  ID Encadrant
                </label>
                <input
                  type="text"
                  name="idEncadrant"
                  id="idEncadrant"
                  className="w-full px-4 py-2 mt-1 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
                  placeholder="Entrez l'ID de l'encadrant"
                  onChange={handleChange}
                  required
                />
              </div>

              {/* Nom */}
              <div className="mb-4">
                <label htmlFor="nom" className="block text-sm font-medium text-gray-700 mb-1">
                  Nom
                </label>
                <input
                  type="text"
                  name="nom"
                  id="nom"
                  className="w-full px-4 py-2 mt-1 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
                  placeholder="Entrez le nom"
                  onChange={handleChange}
                  required
                />
              </div>

              {/* Prénom */}
              <div className="mb-4">
                <label htmlFor="prenom" className="block text-sm font-medium text-gray-700 mb-1">
                  Prénom
                </label>
                <input
                  type="text"
                  name="prenom"
                  id="prenom"
                  className="w-full px-4 py-2 mt-1 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
                  placeholder="Entrez le prénom"
                  onChange={handleChange}
                  required
                />
              </div>

              {/* Email */}
              <div className="mb-4">
                <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-1">
                  Adresse email
                </label>
                <input
                  type="email"
                  name="email"
                  id="email"
                  className="w-full px-4 py-2 mt-1 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
                  placeholder="Entrez l'adresse email"
                  onChange={handleChange}
                  required
                />
              </div>

              {/* Mot de passe */}
              <div className="mb-4">
                <label htmlFor="motDePasse" className="block text-sm font-medium text-gray-700 mb-1">
                  Mot de passe
                </label>
                <input
                  type="password"
                  name="motDePasse"
                  id="motDePasse"
                  className="w-full px-4 py-2 mt-1 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
                  placeholder="Entrez le mot de passe"
                  onChange={handleChange}
                  required
                />
              </div>

              {/* Année */}
              <div className="mb-4">
                <label htmlFor="annee" className="block text-sm font-medium text-gray-700 mb-1">
                  Année d'inscription
                </label>
                <select
                  name="annee"
                  id="annee"
                  value={inputs.annee || ""}
                  className="w-full px-4 py-2 mt-1 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
                  onChange={handleChange}
                  required
                >
                  <option value="" disabled>
                    Sélectionnez une année
                  </option>
                  {Array.from({ length: 20 }, (_, i) => {
                    const year = new Date().getFullYear() - i;
                    return (
                      <option key={year} value={year}>
                        {year}
                      </option>
                    );
                  })}
                </select>
              </div>

              {/* Bouton Ajouter */}
              <button
                type="submit"
                className="w-full bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 focus:ring-2 focus:ring-blue-500 transition-all"
              >
                Ajouter
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Addnewuser;